raw:
{
  "spells": [
    {
      "id": "spell_wind_01",
      "theory": "招风术把魔力注入近处空气，使原本静止的气流沿施术者指定的方向持续流动。它只推动现有空气，不制造新的气体，也不能改变温度或湿度。流动范围以施术者为圆心、两米为半径，最远触及三米处的边缘。烟、粉尘和轻质织物会被气流带走，但烟源本身仍在原地继续产生烟雾，因此无法扑灭火堆或堵住漏烟的缝隙。",
      "casting": "五指微张，掌心朝目标方向缓缓推出，同时以鼻息配合一次短促吐气。推出时手腕保持水平，让气流沿掌心平面铺开。",
      "failure": "气流方向偏斜，只吹动脚边尘土却驱不散面前烟雾；或风力过弱，烟雾只晃动一下便重新聚拢。施术者可能感到指尖发麻，但不会受伤。",
      "counters": [
        "用厚布或木板挡在气流路径上，风便绕行或减弱。",
        "在烟源附近制造逆向的稳定气流，可抵消招风术的推力。"
      ],
      "socialConsequences": "河谷乡民在灶房烟熏时常用它驱烟，但不会用它替代烟囱，因为烟源不灭。城镇居民若在狭窄巷口施放，可能把摊贩的轻质货品吹散，须先提醒邻近摊主。港务人员允许在露天装卸区使用，但若在货舱内使用导致粉尘弥漫，会被追究妨碍作业的责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时气流忽强忽弱，驱烟效果时有时无。",
        "掌握基本推送后，气流能稳定覆盖两米内的固定方向。",
        "熟练者可让气流贴着地面走，减少对高处物品的干扰。",
        "更高熟练度能精确控制边界，不吹动范围外的轻小物件。"
      ]
    },
    {
      "id": "spell_wind_02",
      "theory": "拂尘术将魔力转化为细密而均匀的贴面气流，沿物体表面滑过，把附着力弱的尘土、草屑和干泥粉带离。气流只作用于表面，不渗入织物纤维或木纹深处，因此油渍、霉斑和嵌入缝隙的污物不会被清除。对书籍、皮甲和陶器都有效，但遇水后尘土变泥，效果会大打折扣。",
      "casting": "用食指与中指并拢，在物体上方约一掌宽处画一道短横线，然后向侧面轻扫。扫动时两指保持并拢，避免气流散乱。",
      "failure": "气流过于集中，只在物体表面吹出一道干净痕迹，其余部分尘土依旧；或气流太散，尘土被扬起后重新落回原处。若物体表面有毛刺，可能勾住尘团。",
      "counters": [
        "用湿布覆盖物体表面，尘土遇水后无法被气流带走。",
        "在物体周围放置挡风板，切断贴面气流的连续路径。"
      ],
      "socialConsequences": "河谷乡约见证民事承诺时，常有人用拂尘术清理契约卷轴上的浮尘，以免按印时沾污。中陆城市公会要求档案员定期清理登记簿，但不会因此免除防火和防潮责任。琥珀海岸的港务规定，清理货箱表面浮尘可以公开进行，若尘土被吹入他人货堆或航道，则按货损纠纷处理。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时尘土常被吹到旁边而非彻底离开表面。",
        "稳定施术者能均匀清理桌面和卷轴，不留明显条痕。",
        "熟练者可调整气流角度，清理雕花缝隙边缘的积尘。",
        "更高熟练度使气流贴面更紧，减少扬尘飘散到空气中。"
      ]
    },
    {
      "id": "spell_wind_03",
      "theory": "传声线把施术者的声音送入一条细窄气流，气流沿指定方向延伸，把声波带到三米内。这条气流不隔绝环境噪音，因此沿途的人也能听见传话内容。气流本身不携带魔力伤害，只改变声音的传播路径，不能穿过厚墙或密封门窗。若目标处有强风，声线会被打散。",
      "casting": "嘴唇拢圆，向目标方向轻声说出内容，同时以右手食指在嘴前画一条短弧线。弧线画完即停止送气，声音便沿弧线方向传出。",
      "failure": "声线中途散开，目标只听到模糊音节或完全听不见；若气流方向偏移，声音可能传到旁边的人耳中，造成内容泄露。施术者会感到喉咙略干。",
      "counters": [
        "在声线路径上放置厚布或木板，可吸收并阻断声音。",
        "用更大的环境噪音覆盖声线，使目标无法分辨传话内容。"
      ],
      "socialConsequences": "河谷乡民在集市上常用传声线隔着摊位谈价，但若被旁人听见私密内容，只能怪自己选错了场合。中陆城市公会提醒成员，在听证或仲裁场合使用传声线可能被视为干扰秩序。琥珀海岸的港务规定，用传声线传递船舶调度口令时，若因听错导致碰撞或货损，传话者须承担相应责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时声线常偏离方向，目标听到的音量忽大忽小。",
        "掌握基本弧线后，三米内目标能听清简短语句。",
        "熟练者可让声线更窄，减少沿途旁人听到的内容。",
        "更高熟练度能稳定声线，在嘈杂环境中仍保持可辨度。"
      ]
    }
  ]
}
